#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>
#include <cstdlib>

using namespace std;

long long minimumMoves(const vector<int>& pieces, int n, int parity) {
    const long long INF = numeric_limits<long long>::max() / 4;
    const int m = static_cast<int>(pieces.size());

    vector<long long> dp(m + 1, INF);
    dp[0] = 0;

    int processed = 0;
    for (int target = parity; target <= n; target += 2) {
        ++processed;
        for (int matched = min(m, processed); matched >= 1; --matched) {
            if (dp[matched - 1] != INF) {
                dp[matched] = min(
                    dp[matched],
                    dp[matched - 1] + llabs(
                        static_cast<long long>(pieces[matched - 1]) - target
                    )
                );
            }
        }
    }

    return dp[m];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n) {
        vector<int> pieces(n / 2);
        for (int& position : pieces) {
            cin >> position;
        }

        sort(pieces.begin(), pieces.end());

        cout << min(
            minimumMoves(pieces, n, 1),
            minimumMoves(pieces, n, 2)
        ) << '\n';
    }

    return 0;
}

