#include <iostream>
#include <vector>
#include <queue>
#include <unordered_set>
#include <algorithm>

using namespace std;

struct VectorHash {
    size_t operator()(const vector<int>& state) const noexcept {
        size_t hash = 0;
        for (int position : state) {
            hash ^= std::hash<int>{}(position) + 0x9e3779b9 +
                    (hash << 6) + (hash >> 2);
        }
        return hash;
    }
};

int n, pieces;

bool same_color(const vector<int>& state) {
    if (state.empty())
        return true;

    for (size_t i = 1; i < state.size(); ++i) {
        if (state[i] % 2 != state[0] % 2)
            return false;
    }
    return true;
}

int bfs(vector<int> initial) {
    sort(initial.begin(), initial.end());

    if (same_color(initial))
        return 0;

    queue<pair<vector<int>, int>> states;
    unordered_set<vector<int>, VectorHash> visited;

    states.push({initial, 0});
    visited.insert(initial);

    while (!states.empty()) {
        vector<int> state = std::move(states.front().first);
        int steps = states.front().second;
        states.pop();

        vector<bool> occupied(n + 1, false);
        for (int position : state)
            occupied[position] = true;

        for (int i = 0; i < pieces; ++i) {
            for (int direction : {-1, 1}) {
                int nextPosition = state[i] + direction;

                if (nextPosition < 1 || nextPosition > n ||
                    occupied[nextPosition])
                    continue;

                vector<int> nextState = state;
                nextState[i] = nextPosition;
                sort(nextState.begin(), nextState.end());

                if (!visited.insert(nextState).second)
                    continue;

                if (same_color(nextState))
                    return steps + 1;

                states.push({std::move(nextState), steps + 1});
            }
        }
    }

    return -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (cin >> n) {
        pieces = n / 2;
        vector<int> state(pieces);

        for (int& position : state)
            cin >> position;

        cout << bfs(std::move(state)) << '\n';
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
#include <cstdlib>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n) {
        int pieces = n / 2;
        vector<int> state(pieces);

        for (int& position : state)
            cin >> position;

        sort(state.begin(), state.end());

        if (pieces == 0) {
            cout << 0 << '\n';
            continue;
        }

        long long evenCost = 0;
        for (int i = 0; i < pieces; ++i)
            evenCost += llabs(static_cast<long long>(state[i]) - (2LL * i + 2));

        long long oddCost = LLONG_MAX;

        if (n % 2 == 0) {
            oddCost = 0;
            for (int i = 0; i < pieces; ++i)
                oddCost += llabs(static_cast<long long>(state[i]) - (2LL * i + 1));
        } else {
            vector<long long> prefix(pieces + 1, 0);
            vector<long long> suffix(pieces + 1, 0);

            for (int i = 0; i < pieces; ++i) {
                prefix[i + 1] =
                    prefix[i] +
                    llabs(static_cast<long long>(state[i]) - (2LL * i + 1));
            }

            for (int i = pieces - 1; i >= 0; --i) {
                suffix[i] =
                    suffix[i + 1] +
                    llabs(static_cast<long long>(state[i]) - (2LL * i + 3));
            }

            for (int skipped = 0; skipped <= pieces; ++skipped)
                oddCost = min(oddCost, prefix[skipped] + suffix[skipped]);
        }

        cout << min(evenCost, oddCost) << '\n';
    }

    return 0;
}

